59	+//! Sound controller, IO 0x060-0x0AF (gbatek: GBA Sound Controller).
60	+//!
61	+//! Phase 0 stub: registers are stored and silence is produced at the rate SOUNDBIAS selects,
62	+//! so the host already receives the right number of samples per frame.
63	+
64	+mod fifo;
65	+mod psg;
66	+
67	+use crate::io::PlainRegisters;
68	+
69	+const IO_START: u32 = 0x060; // SOUND1CNT_L, first sound register
70	+const SOUNDBIAS: u32 = 0x088; // sound PWM control: bias level and sampling rate
71	+const SOUNDBIAS_DEFAULT: u16 = 0x0200;
72	+
73	+/// CPU clock in Hz (16 * 1024 * 1024).
74	+const CPU_CLOCK_HZ: u32 = 16 * 1024 * 1024;
75	+/// Base output rate for SOUNDBIAS resolution 0; each resolution step doubles it.
76	+const BASE_SAMPLE_RATE_HZ: u32 = 32768;
77	+/// Stereo pairs kept when the host never drains; older output is dropped beyond this.
78	+const MAX_BUFFERED_PAIRS: usize = 1 << 16;
79	+
80	+pub struct Apu {
81	+    registers: PlainRegisters<0x28>,
82	+    psg: psg::Psg,
83	+    fifos: [fifo::SoundFifo; 2],
84	+    /// Cycles accumulated towards the next output sample.
85	+    cycles_until_sample: u32,
86	+    /// Interleaved stereo i16 output, drained by the host through lib.rs.
87	+    pub samples: Vec<i16>,
88	+}
89	+
90	+impl Apu {
91	+    pub fn new() -> Self {
92	+        let mut registers = PlainRegisters::new(IO_START);
93	+        registers.write(SOUNDBIAS, SOUNDBIAS_DEFAULT, 0xFFFF);
94	+        Apu {
95	+            registers,
96	+            psg: psg::Psg::new(),
97	+            fifos: [fifo::SoundFifo::new(), fifo::SoundFifo::new()],
98	+            cycles_until_sample: 0,
99	+            samples: Vec::with_capacity(MAX_BUFFERED_PAIRS * 2),
100	+        }
101	+    }
102	+
103	+    /// Output sample rate: 32768 Hz shifted left by the SOUNDBIAS resolution bits 14-15.
104	+    pub fn sample_rate(&self) -> u32 {
105	+        let resolution = (self.registers.read(SOUNDBIAS) >> 14) & 3;
106	+        BASE_SAMPLE_RATE_HZ << resolution
107	+    }
108	+
109	+    /// Advance by `cycles`, appending one stereo pair per output sample period.
110	+    pub fn step(&mut self, cycles: u32) {
111	+        let cycles_per_sample = CPU_CLOCK_HZ / self.sample_rate();
112	+        self.cycles_until_sample += cycles;
113	+        while self.cycles_until_sample >= cycles_per_sample {
114	+            self.cycles_until_sample -= cycles_per_sample;
115	+            let (left, right) = self.mix_sample();
116	+            if self.samples.len() < MAX_BUFFERED_PAIRS * 2 {
117	+                self.samples.push(left);
118	+                self.samples.push(right);
119	+            }
120	+        }
121	+    }
122	+
123	+    /// Mix PSG and FIFO channels into one stereo pair. Stub: silence.
124	+    fn mix_sample(&mut self) -> (i16, i16) {
125	+        let _ = (&self.psg, &self.fifos);
126	+        (0, 0)
127	+    }
128	+
129	+    /// Timer `timer_index` overflowed. Returns a bit mask of FIFOs (bit 0 = A, bit 1 = B) that
130	+    /// now need a DMA refill; gba.rs forwards those to the DMA controller.
131	+    pub fn on_timer_overflow(&mut self, _timer_index: usize) -> u8 {
132	+        0
133	+    }
134	+
135	+    pub fn io_read16(&mut self, offset: u32) -> u16 {
136	+        self.registers.read(offset)
137	+    }
138	+
139	+    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
140	+        self.registers.write(offset, value, mask)
141	+    }
142	+}
