165	@@ -0,0 +1,82 @@
166	+//! Native debug tool: run a ROM through the same ABI the grader uses, then dump the last frame.
167	+//!
168	+//!   cargo run --release --bin run_rom -- <rom.gba> <frames> <out.ppm> [out.wav]
169	+
170	+use std::fs;
171	+use std::process::exit;
172	+
173	+use gba_emu::*;
174	+
175	+const WIDTH: usize = 240;
176	+const HEIGHT: usize = 160;
177	+
178	+fn main() {
179	+    let arguments: Vec<String> = std::env::args().collect();
180	+    if arguments.len() < 4 {
181	+        eprintln!("usage: run_rom <rom.gba> <frames> <out.ppm> [out.wav]");
182	+        exit(2);
183	+    }
184	+    let rom = fs::read(&arguments[1]).unwrap_or_else(|error| fail(&format!("read rom: {error}")));
185	+    let frame_count: u32 = arguments[2].parse().unwrap_or_else(|_| fail("frames must be a number"));
186	+
187	+    let mut audio: Vec<i16> = Vec::new();
188	+    // SAFETY: the ABI hands out pointers into buffers that live for the whole program.
189	+    unsafe {
190	+        if emu_init() != 1 {
191	+            fail("emu_init failed");
192	+        }
193	+        if rom.len() > 32 * 1024 * 1024 {
194	+            fail("rom larger than 32 MiB");
195	+        }
196	+        std::ptr::copy_nonoverlapping(rom.as_ptr(), emu_rom_buffer(), rom.len());
197	+        if emu_load_rom(rom.len() as i32) != 1 {
198	+            fail("emu_load_rom failed");
199	+        }
200	+        for _ in 0..frame_count {
201	+            emu_run_frame();
202	+            let pairs = emu_audio_samples() as usize;
203	+            audio.extend_from_slice(std::slice::from_raw_parts(emu_audio_buffer(), pairs * 2));
204	+        }
205	+        let pixels = std::slice::from_raw_parts(emu_framebuffer(), WIDTH * HEIGHT);
206	+        write_ppm(&arguments[3], pixels);
207	+    }
208	+    if let Some(wav_path) = arguments.get(4) {
209	+        write_wav(wav_path, &audio, emu_audio_rate() as u32);
210	+    }
211	+}
212	+
213	+fn fail(message: &str) -> ! {
214	+    eprintln!("run_rom: {message}");
215	+    exit(1);
216	+}
217	+
218	+/// Binary PPM (P6) from 0xAABBGGRR pixels.
219	+fn write_ppm(path: &str, pixels: &[u32]) {
220	+    let mut output = format!("P6\n{WIDTH} {HEIGHT}\n255\n").into_bytes();
221	+    for &pixel in pixels {
222	+        output.extend_from_slice(&[pixel as u8, (pixel >> 8) as u8, (pixel >> 16) as u8]);
223	+    }
224	+    fs::write(path, output).unwrap_or_else(|error| fail(&format!("write ppm: {error}")));
225	+}
226	+
227	+/// 16-bit stereo PCM WAV.
228	+fn write_wav(path: &str, samples: &[i16], sample_rate: u32) {
229	+    let data_bytes = (samples.len() * 2) as u32;
230	+    let mut output = Vec::with_capacity(44 + data_bytes as usize);
231	+    output.extend_from_slice(b"RIFF");
232	+    output.extend_from_slice(&(36 + data_bytes).to_le_bytes());
233	+    output.extend_from_slice(b"WAVEfmt ");
234	+    output.extend_from_slice(&16u32.to_le_bytes()); // fmt chunk size
235	+    output.extend_from_slice(&1u16.to_le_bytes()); // PCM
236	+    output.extend_from_slice(&2u16.to_le_bytes()); // channels
237	+    output.extend_from_slice(&sample_rate.to_le_bytes());
238	+    output.extend_from_slice(&(sample_rate * 4).to_le_bytes()); // byte rate
239	+    output.extend_from_slice(&4u16.to_le_bytes()); // block align
240	+    output.extend_from_slice(&16u16.to_le_bytes()); // bits per sample
241	+    output.extend_from_slice(b"data");
242	+    output.extend_from_slice(&data_bytes.to_le_bytes());
243	+    for sample in samples {
244	+        output.extend_from_slice(&sample.to_le_bytes());
245	+    }
246	+    fs::write(path, output).unwrap_or_else(|error| fail(&format!("write wav: {error}")));
247	+}
