254	+//! System bus: memory map, region dispatch and access-cycle costs (gbatek: GBA Memory Map).
255	+//!
256	+//! The CPU only ever talks to the bus. Every access adds its cycle cost to `access_cycles`,
257	+//! which the CPU drains with `take_access_cycles()` to report how long a step took.
258	+
259	+use crate::apu::Apu;
260	+use crate::cart::Cart;
261	+use crate::dma::Dma;
262	+use crate::io::SerialStub;
263	+use crate::irq::Irq;
264	+use crate::keypad::Keypad;
265	+use crate::ppu::Ppu;
266	+use crate::timer::Timers;
267	+
268	+/// The 16 KiB BIOS stub supplied by the benchmark, mapped at 0x00000000.
269	+static BIOS: &[u8; BIOS_SIZE] = include_bytes!("../assets/gba_bios_stub.bin");
270	+
271	+pub const BIOS_SIZE: usize = 0x4000;
272	+pub const EWRAM_SIZE: usize = 0x40000; // on-board work RAM, 256 KiB
273	+pub const IWRAM_SIZE: usize = 0x8000; // on-chip work RAM, 32 KiB
274	+
275	+/// Access width, used to pick the cycle cost.
276	+#[derive(Clone, Copy, PartialEq, Eq, Debug)]
277	+pub enum Width {
278	+    Byte,
279	+    Halfword,
280	+    Word,
281	+}
282	+
283	+/// Memory regions, selected by address bits 24-27.
284	+#[derive(Clone, Copy, PartialEq, Eq, Debug)]
285	+enum Region {
286	+    Bios,
287	+    Ewram,
288	+    Iwram,
289	+    Io,
290	+    Palette,
291	+    Vram,
292	+    Oam,
293	+    Rom,
294	+    Sram,
295	+    Unmapped,
296	+}
297	+
298	+fn region_of(address: u32) -> Region {
299	+    match address >> 24 {
300	+        0x00 => Region::Bios,
301	+        0x02 => Region::Ewram,
302	+        0x03 => Region::Iwram,
303	+        0x04 => Region::Io,
304	+        0x05 => Region::Palette,
305	+        0x06 => Region::Vram,
306	+        0x07 => Region::Oam,
307	+        0x08..=0x0D => Region::Rom,
308	+        0x0E | 0x0F => Region::Sram,
309	+        _ => Region::Unmapped,
310	+    }
311	+}
312	+
313	+/// Cycle cost with default wait states (gbatek: GBA Memory Map, "Address Bus Width and CPU
314	+/// Read/Write Access Widths").
315	+// ponytail: fixed default wait states, no WAITCNT, no sequential/non-sequential split, no
316	+// video-memory contention; Phase 2/5 wire WAITCNT and prefetch in here.
317	+fn access_cost(region: Region, width: Width) -> u32 {
318	+    let is_word = width == Width::Word;
319	+    match region {
320	+        Region::Bios | Region::Iwram | Region::Io | Region::Oam | Region::Unmapped => 1,
321	+        Region::Ewram => if is_word { 6 } else { 3 },
322	+        Region::Palette | Region::Vram => if is_word { 2 } else { 1 },
323	+        Region::Rom => if is_word { 8 } else { 5 },
324	+        Region::Sram => 5,
325	+    }
326	+}
327	+
328	+/// Offset into VRAM: 96 KiB mirrored in 128 KiB steps, the upper 32 KiB mirroring 0x10000-0x17FFF.
329	+fn vram_offset(address: u32) -> usize {
330	+    let offset = address & 0x1FFFF;
331	+    (if offset >= 0x18000 { offset - 0x8000 } else { offset }) as usize
332	+}
333	+
334	+fn read_le16(memory: &[u8], offset: usize) -> u16 {
335	+    u16::from_le_bytes([memory[offset], memory[offset + 1]])
336	+}
337	+
338	+fn read_le32(memory: &[u8], offset: usize) -> u32 {
339	+    u32::from_le_bytes([memory[offset], memory[offset + 1], memory[offset + 2], memory[offset + 3]])
340	+}
341	+
342	+fn write_le16(memory: &mut [u8], offset: usize, value: u16) {
343	+    memory[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
344	+}
345	+
346	+fn write_le32(memory: &mut [u8], offset: usize, value: u32) {
347	+    memory[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
348	+}
349	+
350	+pub struct Bus {
351	+    pub ewram: Vec<u8>,
352	+    pub iwram: Vec<u8>,
353	+    pub ppu: Ppu, // also owns palette RAM, VRAM and OAM
354	+    pub apu: Apu,
355	+    pub dma: Dma,
356	+    pub timers: Timers,
357	+    pub keypad: Keypad,
358	+    pub serial: SerialStub,
359	+    pub irq: Irq,
360	+    pub cart: Cart,
361	+    /// Cycles spent on accesses since the last `take_access_cycles()`.
362	+    pub access_cycles: u32,
363	+}
364	+
365	+impl Bus {
366	+    pub fn new(rom: &[u8]) -> Self {
367	+        Bus {
368	+            ewram: vec![0; EWRAM_SIZE],
369	+            iwram: vec![0; IWRAM_SIZE],
370	+            ppu: Ppu::new(),
371	+            apu: Apu::new(),
372	+            dma: Dma::new(),
373	+            timers: Timers::new(),
374	+            keypad: Keypad::new(),
375	+            serial: SerialStub::new(),
376	+            irq: Irq::new(),
377	+            cart: Cart::new(rom),
378	+            access_cycles: 0,
379	+        }
380	+    }
381	+
382	+    /// Return and reset the cycles spent on bus accesses.
383	+    pub fn take_access_cycles(&mut self) -> u32 {
384	+        std::mem::take(&mut self.access_cycles)
385	+    }
386	+
387	+    fn charge(&mut self, address: u32, width: Width) -> Region {
388	+        let region = region_of(address);
389	+        self.access_cycles += access_cost(region, width);
390	+        region
391	+    }
392	+
393	+    pub fn read8(&mut self, address: u32) -> u8 {
394	+        match self.charge(address, Width::Byte) {
395	+            Region::Bios => bios_read(address, 1) as u8,
396	+            Region::Ewram => self.ewram[(address as usize) & (EWRAM_SIZE - 1)],
397	+            Region::Iwram => self.iwram[(address as usize) & (IWRAM_SIZE - 1)],
398	+            Region::Io => self.io_read8(io_offset(address)),
399	+            Region::Palette => self.ppu.palette[(address & 0x3FF) as usize],
400	+            Region::Vram => self.ppu.vram[vram_offset(address)],
401	+            Region::Oam => self.ppu.oam[(address & 0x3FF) as usize],
402	+            Region::Rom => self.cart.rom_read8(address),
403	+            Region::Sram => self.cart.sram_read8(address),
404	+            Region::Unmapped => 0,
405	+        }
406	+    }
407	+
408	+    pub fn read16(&mut self, address: u32) -> u16 {
409	+        // ponytail: misaligned addresses are force-aligned; rotation of misaligned reads belongs to the CPU.
410	+        let address = address & !1;
411	+        match self.charge(address, Width::Halfword) {
412	+            Region::Bios => bios_read(address, 2) as u16,
413	+            Region::Ewram => read_le16(&self.ewram, (address as usize) & (EWRAM_SIZE - 1)),
414	+            Region::Iwram => read_le16(&self.iwram, (address as usize) & (IWRAM_SIZE - 1)),
415	+            Region::Io => self.io_read16(io_offset(address)),
416	+            Region::Palette => read_le16(&self.ppu.palette, (address & 0x3FF) as usize),
417	+            Region::Vram => read_le16(&self.ppu.vram, vram_offset(address)),
418	+            Region::Oam => read_le16(&self.ppu.oam, (address & 0x3FF) as usize),
419	+            Region::Rom => self.cart.rom_read16(address),
420	+            Region::Sram => self.cart.sram_read8(address) as u16 * 0x0101,
421	+            Region::Unmapped => 0,
422	+        }
423	+    }
424	+
425	+    pub fn read32(&mut self, address: u32) -> u32 {
426	+        let address = address & !3;
427	+        match self.charge(address, Width::Word) {
428	+            Region::Bios => bios_read(address, 4),
429	+            Region::Ewram => read_le32(&self.ewram, (address as usize) & (EWRAM_SIZE - 1)),
430	+            Region::Iwram => read_le32(&self.iwram, (address as usize) & (IWRAM_SIZE - 1)),
431	+            Region::Io => self.io_read32(io_offset(address)),
432	+            Region::Palette => read_le32(&self.ppu.palette, (address & 0x3FF) as usize),
433	+            Region::Vram => read_le32(&self.ppu.vram, vram_offset(address)),
434	+            Region::Oam => read_le32(&self.ppu.oam, (address & 0x3FF) as usize),
435	+            Region::Rom => {
436	+                let low = self.cart.rom_read16(address) as u32;
437	+                let high = self.cart.rom_read16(address + 2) as u32;
438	+                low | (high << 16)
439	+            }
440	+            Region::Sram => self.cart.sram_read8(address) as u32 * 0x0101_0101,
441	+            Region::Unmapped => 0,
442	+        }
443	+    }
444	+
445	+    pub fn write8(&mut self, address: u32, value: u8) {
446	+        match self.charge(address, Width::Byte) {
447	+            Region::Ewram => self.ewram[(address as usize) & (EWRAM_SIZE - 1)] = value,
448	+            Region::Iwram => self.iwram[(address as usize) & (IWRAM_SIZE - 1)] = value,
449	+            Region::Io => self.io_write8(io_offset(address), value),
450	+            // Palette and VRAM have a 16-bit data bus: a byte write lands in both halves.
451	+            // ponytail: VRAM byte writes into the OBJ area should be ignored; mode-dependent, left to the PPU agent.
452	+            Region::Palette => {
453	+                write_le16(&mut self.ppu.palette, (address & 0x3FE) as usize, value as u16 * 0x0101)
454	+            }
455	+            Region::Vram => {
456	+                write_le16(&mut self.ppu.vram, vram_offset(address & !1), value as u16 * 0x0101)
457	+            }
458	+            Region::Oam => {} // OAM ignores 8-bit writes
459	+            Region::Sram => self.cart.sram_write8(address, value),
460	+            Region::Bios | Region::Rom | Region::Unmapped => {}
461	+        }
462	+    }
463	+
464	+    pub fn write16(&mut self, address: u32, value: u16) {
465	+        let address = address & !1;
466	+        match self.charge(address, Width::Halfword) {
467	+            Region::Ewram => write_le16(&mut self.ewram, (address as usize) & (EWRAM_SIZE - 1), value),
468	+            Region::Iwram => write_le16(&mut self.iwram, (address as usize) & (IWRAM_SIZE - 1), value),
469	+            Region::Io => self.io_write16(io_offset(address), value),
470	+            Region::Palette => write_le16(&mut self.ppu.palette, (address & 0x3FF) as usize, value),
471	+            Region::Vram => write_le16(&mut self.ppu.vram, vram_offset(address), value),
472	+            Region::Oam => write_le16(&mut self.ppu.oam, (address & 0x3FF) as usize, value),
473	+            Region::Sram => self.cart.sram_write8(address, value as u8),
474	+            Region::Rom => self.cart.rom_write16(address, value),
475	+            Region::Bios | Region::Unmapped => {}
476	+        }
477	+    }
478	+
479	+    pub fn write32(&mut self, address: u32, value: u32) {
480	+        let address = address & !3;
481	+        match self.charge(address, Width::Word) {
482	+            Region::Ewram => write_le32(&mut self.ewram, (address as usize) & (EWRAM_SIZE - 1), value),
483	+            Region::Iwram => write_le32(&mut self.iwram, (address as usize) & (IWRAM_SIZE - 1), value),
484	+            Region::Io => self.io_write32(io_offset(address), value),
485	+            Region::Palette => write_le32(&mut self.ppu.palette, (address & 0x3FF) as usize, value),
486	+            Region::Vram => write_le32(&mut self.ppu.vram, vram_offset(address), value),
487	+            Region::Oam => write_le32(&mut self.ppu.oam, (address & 0x3FF) as usize, value),
488	+            Region::Sram => self.cart.sram_write8(address, value as u8),
489	+            Region::Rom => {
490	+                self.cart.rom_write16(address, value as u16);
491	+                self.cart.rom_write16(address + 2, (value >> 16) as u16);
492	+            }
493	+            Region::Bios | Region::Unmapped => {}
494	+        }
495	+    }
496	+}
497	+
498	+/// IO offset from 0x04000000. Only 0x000-0x3FF and 0x800-0x803 are registers; the rest reads 0.
499	+fn io_offset(address: u32) -> u32 {
500	+    let offset = address & 0x00FF_FFFF;
501	+    if offset < 0x400 || (0x800..0x804).contains(&offset) {
502	+        offset
503	+    } else {
504	+        0xFFFF_FFFF // no owner: io.rs treats it as unmapped
505	+    }
506	+}
507	+
508	+/// Little-endian read of `size` bytes from the BIOS. Outside 0x0000-0x3FFF reads 0.
509	+// ponytail: no BIOS read protection (last-fetched-opcode value); add when a test reads BIOS from ROM code.
510	+fn bios_read(address: u32, size: usize) -> u32 {
511	+    let offset = address as usize;
512	+    if offset + size > BIOS_SIZE {
513	+        return 0;
514	+    }
515	+    (0..size).fold(0, |value, i| value | (BIOS[offset + i] as u32) << (8 * i))
516	+}
517	+
518	+#[cfg(test)]
519	+mod tests {
520	+    use super::*;
521	+
522	+    #[test]
523	+    fn round_trip_every_width_in_ram_regions() {
524	+        let mut bus = Bus::new(&[]);
525	+        for base in [0x0200_0000u32, 0x0300_0000, 0x0500_0000, 0x0600_0000, 0x0700_0000] {
526	+            bus.write32(base + 0x10, 0xDEAD_BEEF);
527	+            assert_eq!(bus.read32(base + 0x10), 0xDEAD_BEEF, "word at {base:#x}");
528	+            assert_eq!(bus.read16(base + 0x12), 0xDEAD, "high halfword at {base:#x}");
529	+            assert_eq!(bus.read8(base + 0x10), 0xEF, "low byte at {base:#x}");
530	+
531	+            bus.write16(base + 0x20, 0x1234);
532	+            assert_eq!(bus.read16(base + 0x20), 0x1234, "halfword at {base:#x}");
533	+        }
534	+        for base in [0x0200_0000u32, 0x0300_0000] {
535	+            bus.write8(base + 0x31, 0xAB);
536	+            assert_eq!(bus.read8(base + 0x31), 0xAB, "byte at {base:#x}");
537	+        }
538	+        // Mirrors: EWRAM every 256 KiB, IWRAM every 32 KiB.
539	+        assert_eq!(bus.read32(0x0204_0010), 0xDEAD_BEEF);
540	+        assert_eq!(bus.read32(0x0300_8010), 0xDEAD_BEEF);
541	+    }
542	+
543	+    #[test]
544	+    fn bios_is_mapped_and_read_only() {
545	+        let mut bus = Bus::new(&[]);
546	+        let reset_vector = bus.read32(0);
547	+        assert_eq!(reset_vector, u32::from_le_bytes([BIOS[0], BIOS[1], BIOS[2], BIOS[3]]));
548	+        bus.write32(0, 0);
549	+        assert_eq!(bus.read32(0), reset_vector);
550	+    }
551	+
552	+    #[test]
553	+    fn io_byte_write_acknowledges_only_its_own_if_bits() {
554	+        let mut bus = Bus::new(&[]);
555	+        bus.irq.interrupt_flags = 0x0101;
556	+        bus.write8(0x0400_0202, 0x01); // acknowledge bit 0 only
557	+        assert_eq!(bus.read16(0x0400_0202), 0x0100);
558	+        bus.write32(0x0400_0200, 0x0000_3FFF); // IE = all, IF write of 0 clears nothing
559	+        assert_eq!(bus.read32(0x0400_0200), 0x0100_3FFF);
560	+    }
561	+
562	+    #[test]
563	+    fn access_cycles_follow_default_wait_states() {
564	+        let mut bus = Bus::new(&[]);
565	+        bus.read32(0x0200_0000);
566	+        assert_eq!(bus.take_access_cycles(), 6);
567	+        bus.read16(0x0800_0000);
568	+        assert_eq!(bus.take_access_cycles(), 5);
569	+    }
570	+}
