770	+//! The whole machine: CPU plus bus (which owns every other component), and the frame loop.
771	+//!
772	+//! Events between components (PPU -> DMA, timers -> APU, APU -> DMA) are plain method calls here,
773	+//! so no component holds a reference to another.
774	+
775	+use crate::bus::Bus;
776	+use crate::cpu::Cpu;
777	+use crate::dma;
778	+use crate::ppu::CYCLES_PER_LINE;
779	+use crate::scheduler::Scheduler;
780	+
781	+/// 228 lines x 1232 cycles (gbatek: LCD Dimensions and Timings).
782	+pub const CYCLES_PER_FRAME: u32 = 280_896;
783	+
784	+/// Scanline at whose start `run_frame` returns. 160 = frame ends at the start of VBlank (the
785	+/// picture is complete and the game's VBlank handler runs after the host sets the next keys);
786	+/// 0 = frame ends at the start of the next frame's drawing. Must match Mesen2's frame boundary:
787	+/// the integrator compares early frames with the reference and changes this one value if needed.
788	+/// Every frame is exactly `CYCLES_PER_FRAME` long; only the first frame after reset is shorter
789	+/// (it runs from line 0 to this line).
790	+pub const FRAME_END_LINE: u32 = 160;
791	+
792	+pub struct Gba {
793	+    pub cpu: Cpu,
794	+    pub bus: Bus,
795	+    pub scheduler: Scheduler,
796	+    /// Cycles left before the current frame ends; overshoot carries into the next frame.
797	+    cycles_until_frame_end: i64,
798	+}
799	+
800	+impl Gba {
801	+    /// Power-on state with `rom` inserted. The CPU starts at the BIOS reset vector.
802	+    pub fn new(rom: &[u8]) -> Self {
803	+        let first_frame_cycles = match FRAME_END_LINE * CYCLES_PER_LINE {
804	+            0 => CYCLES_PER_FRAME,
805	+            cycles => cycles,
806	+        };
807	+        Gba {
808	+            cpu: Cpu::new(),
809	+            bus: Bus::new(rom),
810	+            scheduler: Scheduler::new(),
811	+            cycles_until_frame_end: first_frame_cycles as i64,
812	+        }
813	+    }
814	+
815	+    /// Latch the host key state (ABI bit order, active high).
816	+    pub fn set_keys(&mut self, pressed_keys: u32) {
817	+        self.bus.keypad.set_keys(pressed_keys);
818	+    }
819	+
820	+    /// Run until the frame boundary (see `FRAME_END_LINE`).
821	+    pub fn run_frame(&mut self) {
822	+        while self.cycles_until_frame_end > 0 {
823	+            let mut cycles = self.cpu.step(&mut self.bus);
824	+            cycles += dma::run_pending_transfers(&mut self.bus);
825	+            self.advance_components(cycles);
826	+            self.cycles_until_frame_end -= cycles as i64;
827	+        }
828	+        self.cycles_until_frame_end += CYCLES_PER_FRAME as i64;
829	+    }
830	+
831	+    /// Advance PPU, timers and APU by `cycles` and route their events.
832	+    fn advance_components(&mut self, cycles: u32) {
833	+        let bus = &mut self.bus;
834	+        self.scheduler.advance(cycles);
835	+
836	+        let ppu_events = bus.ppu.step(cycles, &mut bus.irq);
837	+        if ppu_events.hblank_started {
838	+            bus.dma.notify_hblank();
839	+        }
840	+        if ppu_events.vblank_started {
841	+            bus.dma.notify_vblank();
842	+        }
843	+
844	+        let overflowed_timers = bus.timers.step(cycles, &mut bus.irq);
845	+        for timer_index in 0..4 {
846	+            if overflowed_timers & (1 << timer_index) == 0 {
847	+                continue;
848	+            }
849	+            let fifo_requests = bus.apu.on_timer_overflow(timer_index);
850	+            for fifo_index in 0..2 {
851	+                if fifo_requests & (1 << fifo_index) != 0 {
852	+                    bus.dma.notify_fifo_request(fifo_index);
853	+                }
854	+            }
855	+        }
856	+
857	+        bus.apu.step(cycles);
858	+    }
859	+}
860	+
861	+#[cfg(test)]
862	+mod tests {
863	+    use super::*;
864	+
865	+    #[test]
866	+    fn frames_keep_line_timing_aligned() {
867	+        let mut gba = Gba::new(&[]);
868	+        gba.run_frame();
869	+        assert_eq!(gba.bus.ppu.vcount as u32, FRAME_END_LINE % 228);
870	+        let after_first = gba.scheduler.total_cycles;
871	+        gba.run_frame();
872	+        assert_eq!(gba.scheduler.total_cycles - after_first, CYCLES_PER_FRAME as u64);
873	+        assert_eq!(gba.bus.ppu.vcount as u32, FRAME_END_LINE % 228);
874	+    }
875	+
876	+    #[test]
877	+    fn vblank_irq_is_requested_when_enabled() {
878	+        let mut gba = Gba::new(&[]);
879	+        gba.bus.write16(0x0400_0004, 1 << 3); // DISPSTAT: VBlank IRQ enable
880	+        gba.run_frame();
881	+        gba.run_frame();
882	+        assert_ne!(gba.bus.irq.interrupt_flags & 1, 0);
883	+    }
884	+}
