891	+//! IO register dispatch: maps an offset inside 0x04000000 to the component that owns it
892	+//! (gbatek: GBA I/O Map).
893	+//!
894	+//! Every owner exposes `io_read16(offset) -> u16` and `io_write16(offset, value, mask)`, where
895	+//! `offset` is the halfword-aligned offset from 0x04000000 and `mask` marks the bytes really written
896	+//! (0x00FF / 0xFF00 for 8-bit writes, 0xFFFF otherwise). 8- and 32-bit accesses are split or merged
897	+//! here, so owners only ever see halfwords. The mask matters for registers where a read-modify-write
898	+//! would be wrong: IF acknowledge, HALTCNT, the sound FIFOs, write-only registers.
899	+
900	+use crate::bus::Bus;
901	+
902	+/// Owner ranges, inclusive (PLAN.md section 2).
903	+const PPU_RANGE: (u32, u32) = (0x000, 0x05F);
904	+const APU_RANGE: (u32, u32) = (0x060, 0x0AF);
905	+const DMA_RANGE: (u32, u32) = (0x0B0, 0x0DF);
906	+const TIMER_RANGE: (u32, u32) = (0x100, 0x10F);
907	+const SERIAL_LOW_RANGE: (u32, u32) = (0x120, 0x12F);
908	+const KEYPAD_RANGE: (u32, u32) = (0x130, 0x133);
909	+const SERIAL_HIGH_RANGE: (u32, u32) = (0x134, 0x15F);
910	+const SYSTEM_RANGE: (u32, u32) = (crate::irq::IO_START, crate::irq::IO_END);
911	+
912	+/// Replace only the masked bits of `old` with those of `new`. Shared helper for every owner.
913	+pub fn merge(old: u16, new: u16, mask: u16) -> u16 {
914	+    (old & !mask) | (new & mask)
915	+}
916	+
917	+fn in_range(offset: u32, range: (u32, u32)) -> bool {
918	+    offset >= range.0 && offset <= range.1
919	+}
920	+
921	+/// Plain halfword storage for a block of IO registers starting at `base`. Stubs and simple
922	+/// owners use it so a write reads back unchanged.
923	+pub struct PlainRegisters<const HALFWORDS: usize> {
924	+    base: u32,
925	+    values: [u16; HALFWORDS],
926	+}
927	+
928	+impl<const HALFWORDS: usize> PlainRegisters<HALFWORDS> {
929	+    pub fn new(base: u32) -> Self {
930	+        PlainRegisters { base, values: [0; HALFWORDS] }
931	+    }
932	+
933	+    pub fn read(&self, offset: u32) -> u16 {
934	+        self.values[((offset - self.base) / 2) as usize]
935	+    }
936	+
937	+    pub fn write(&mut self, offset: u32, value: u16, mask: u16) {
938	+        let slot = &mut self.values[((offset - self.base) / 2) as usize];
939	+        *slot = merge(*slot, value, mask);
940	+    }
941	+}
942	+
943	+/// Serial port registers 0x120-0x15F (SIOCNT, SIODATA, RCNT, JOY_*): plain storage, never connected.
944	+pub struct SerialStub {
945	+    registers: PlainRegisters<0x20>,
946	+}
947	+
948	+impl SerialStub {
949	+    pub fn new() -> Self {
950	+        SerialStub { registers: PlainRegisters::new(SERIAL_LOW_RANGE.0) }
951	+    }
952	+
953	+    pub fn io_read16(&mut self, offset: u32) -> u16 {
954	+        self.registers.read(offset)
955	+    }
956	+
957	+    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
958	+        self.registers.write(offset, value, mask)
959	+    }
960	+}
961	+
962	+impl Bus {
963	+    /// Route a halfword read to its owner. Unmapped offsets read as 0.
964	+    // ponytail: unmapped reads return 0, not open bus; Phase 2 integrator adds open bus.
965	+    fn io_dispatch_read16(&mut self, offset: u32) -> u16 {
966	+        if in_range(offset, PPU_RANGE) {
967	+            self.ppu.io_read16(offset)
968	+        } else if in_range(offset, APU_RANGE) {
969	+            self.apu.io_read16(offset)
970	+        } else if in_range(offset, DMA_RANGE) {
971	+            self.dma.io_read16(offset)
972	+        } else if in_range(offset, TIMER_RANGE) {
973	+            self.timers.io_read16(offset)
974	+        } else if in_range(offset, KEYPAD_RANGE) {
975	+            self.keypad.io_read16(offset)
976	+        } else if in_range(offset, SERIAL_LOW_RANGE) || in_range(offset, SERIAL_HIGH_RANGE) {
977	+            self.serial.io_read16(offset)
978	+        } else if in_range(offset, SYSTEM_RANGE) {
979	+            self.irq.io_read16(offset)
980	+        } else {
981	+            0
982	+        }
983	+    }
984	+
985	+    /// Route a halfword write (with byte mask) to its owner. Unmapped offsets are ignored.
986	+    fn io_dispatch_write16(&mut self, offset: u32, value: u16, mask: u16) {
987	+        if in_range(offset, PPU_RANGE) {
988	+            self.ppu.io_write16(offset, value, mask)
989	+        } else if in_range(offset, APU_RANGE) {
990	+            self.apu.io_write16(offset, value, mask)
991	+        } else if in_range(offset, DMA_RANGE) {
992	+            self.dma.io_write16(offset, value, mask)
993	+        } else if in_range(offset, TIMER_RANGE) {
994	+            self.timers.io_write16(offset, value, mask)
995	+        } else if in_range(offset, KEYPAD_RANGE) {
996	+            self.keypad.io_write16(offset, value, mask)
997	+        } else if in_range(offset, SERIAL_LOW_RANGE) || in_range(offset, SERIAL_HIGH_RANGE) {
998	+            self.serial.io_write16(offset, value, mask)
999	+        } else if in_range(offset, SYSTEM_RANGE) {
1000	+            self.irq.io_write16(offset, value, mask)
1001	+        }
1002	+    }
1003	+
1004	+    pub fn io_read8(&mut self, offset: u32) -> u8 {
1005	+        let halfword = self.io_dispatch_read16(offset & !1);
1006	+        (halfword >> ((offset & 1) * 8)) as u8
1007	+    }
1008	+
1009	+    pub fn io_read16(&mut self, offset: u32) -> u16 {
1010	+        self.io_dispatch_read16(offset & !1)
1011	+    }
1012	+
1013	+    pub fn io_read32(&mut self, offset: u32) -> u32 {
1014	+        let aligned = offset & !3;
1015	+        let low = self.io_dispatch_read16(aligned) as u32;
1016	+        let high = self.io_dispatch_read16(aligned + 2) as u32;
1017	+        low | (high << 16)
1018	+    }
1019	+
1020	+    pub fn io_write8(&mut self, offset: u32, value: u8) {
1021	+        let shift = (offset & 1) * 8;
1022	+        let halfword = (value as u16) << shift;
1023	+        let mask = 0xFFu16 << shift;
1024	+        self.io_dispatch_write16(offset & !1, halfword, mask);
1025	+    }
1026	+
1027	+    pub fn io_write16(&mut self, offset: u32, value: u16) {
1028	+        self.io_dispatch_write16(offset & !1, value, 0xFFFF);
1029	+    }
1030	+
1031	+    pub fn io_write32(&mut self, offset: u32, value: u32) {
1032	+        let aligned = offset & !3;
1033	+        self.io_dispatch_write16(aligned, value as u16, 0xFFFF);
1034	+        self.io_dispatch_write16(aligned + 2, (value >> 16) as u16, 0xFFFF);
1035	+    }
1036	+}
