1043	+//! Interrupt controller and system-control IO range 0x200-0x804 (gbatek: GBA Interrupt Control).
1044	+//!
1045	+//! Any component raises an interrupt with `irq.request(IrqSource::...)`. Only the CPU consumes them,
1046	+//! through `pending()`.
1047	+
1048	+use crate::io::{merge, PlainRegisters};
1049	+
1050	+const IE: u32 = 0x200; // interrupt enable
1051	+const IF: u32 = 0x202; // interrupt request flags / acknowledge
1052	+const IME: u32 = 0x208; // interrupt master enable
1053	+const POSTFLG_HALTCNT: u32 = 0x300; // low byte POSTFLG (post-boot flag), high byte HALTCNT (low-power mode)
1054	+
1055	+/// First IO offset owned by this module.
1056	+pub const IO_START: u32 = 0x200;
1057	+/// Last IO offset owned by this module (inclusive; 0x800 is the internal memory control register).
1058	+pub const IO_END: u32 = 0x804;
1059	+
1060	+/// IE/IF bit 14-15 are unused.
1061	+const VALID_IRQ_BITS: u16 = 0x3FFF;
1062	+
1063	+/// Interrupt sources, numbered by their IE/IF bit (gbatek: GBA Interrupt Control).
1064	+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
1065	+pub enum IrqSource {
1066	+    VBlank = 0,
1067	+    HBlank = 1,
1068	+    VCounterMatch = 2,
1069	+    Timer0 = 3,
1070	+    Timer1 = 4,
1071	+    Timer2 = 5,
1072	+    Timer3 = 6,
1073	+    Serial = 7,
1074	+    Dma0 = 8,
1075	+    Dma1 = 9,
1076	+    Dma2 = 10,
1077	+    Dma3 = 11,
1078	+    Keypad = 12,
1079	+    GamePak = 13,
1080	+}
1081	+
1082	+pub struct Irq {
1083	+    pub interrupt_enable: u16,
1084	+    pub interrupt_flags: u16,
1085	+    pub master_enable: bool,
1086	+    /// Set by a write to HALTCNT; the CPU clears it when an enabled interrupt wakes it.
1087	+    pub halt_requested: bool,
1088	+    /// Plain storage for the rest of 0x200-0x804 (WAITCNT, POSTFLG, ...), indexed by halfword.
1089	+    other_registers: PlainRegisters<{ ((IO_END - IO_START) / 2 + 1) as usize }>,
1090	+}
1091	+
1092	+impl Irq {
1093	+    pub fn new() -> Self {
1094	+        Irq {
1095	+            interrupt_enable: 0,
1096	+            interrupt_flags: 0,
1097	+            master_enable: false,
1098	+            halt_requested: false,
1099	+            other_registers: PlainRegisters::new(IO_START),
1100	+        }
1101	+    }
1102	+
1103	+    /// Raise an interrupt request flag in IF.
1104	+    pub fn request(&mut self, source: IrqSource) {
1105	+        self.interrupt_flags |= 1 << source as u16;
1106	+    }
1107	+
1108	+    /// True when IME is on and some interrupt is both enabled (IE) and requested (IF).
1109	+    /// The CPSR I bit is the CPU's business.
1110	+    pub fn pending(&self) -> bool {
1111	+        self.master_enable && (self.interrupt_enable & self.interrupt_flags & VALID_IRQ_BITS) != 0
1112	+    }
1113	+
1114	+    pub fn io_read16(&mut self, offset: u32) -> u16 {
1115	+        match offset {
1116	+            IE => self.interrupt_enable,
1117	+            IF => self.interrupt_flags,
1118	+            IME => self.master_enable as u16,
1119	+            _ => self.other_registers.read(offset),
1120	+        }
1121	+    }
1122	+
1123	+    /// `mask` marks the bytes actually written (0x00FF, 0xFF00 or 0xFFFF); see io.rs.
1124	+    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
1125	+        let written = value & mask;
1126	+        match offset {
1127	+            IE => self.interrupt_enable = merge(self.interrupt_enable, value, mask) & VALID_IRQ_BITS,
1128	+            // Writing 1 to an IF bit acknowledges (clears) it.
1129	+            IF => self.interrupt_flags &= !written,
1130	+            IME => self.master_enable = merge(self.master_enable as u16, value, mask) & 1 != 0,
1131	+            _ => {
1132	+                if offset == POSTFLG_HALTCNT && mask & 0xFF00 != 0 {
1133	+                    // ponytail: HALTCNT bit 7 (stop mode) is treated as halt too; add stop when a ROM needs it.
1134	+                    self.halt_requested = true;
1135	+                }
1136	+                self.other_registers.write(offset, value, mask);
1137	+            }
1138	+        }
1139	+    }
1140	+}
