1518	+    /// Advance line timing by `cycles`, raising HBlank/VBlank/VCount IRQs on `irq`.
1519	+    pub fn step(&mut self, cycles: u32, irq: &mut Irq) -> PpuEvents {
1520	+        let mut events = PpuEvents::default();
1521	+        let mut remaining = cycles;
1522	+        while remaining > 0 {
1523	+            let next_boundary =
1524	+                if self.line_cycle < HBLANK_START_CYCLE { HBLANK_START_CYCLE } else { CYCLES_PER_LINE };
