1587	+    pub fn io_read16(&mut self, offset: u32) -> u16 {
1588	+        match offset {
1589	+            DISPSTAT => self.dispstat,
1590	+            VCOUNT => self.vcount,
1591	+            _ => self.registers.read(offset),
1592	+        }
1593	+    }
1594	+
1595	+    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
1596	+        match offset {
1597	+            DISPSTAT => self.dispstat = merge(self.dispstat, value, mask & DISPSTAT_WRITABLE),
1598	+            VCOUNT => {}
1599	+            _ => self.registers.write(offset, value, mask),
1600	+        }
1601	+    }
1602	+}
