1420	+//! LCD video controller, IO 0x000-0x05F: line timing, DISPSTAT/VCOUNT, framebuffer
1421	+//! (gbatek: GBA LCD Video Controller, LCD Dimensions and Timings, LCD I/O Display Control).
1422	+//!
1423	+//! The PPU owns palette RAM, VRAM and OAM; the bus reads and writes them directly.
1424	+//! Phase 0: real line timing and IRQs, no rendering (every visible line is drawn black).
1425	+
1426	+mod bg_affine;
1427	+mod bg_text;
1428	+mod bitmap;
1429	+mod effects;
1430	+mod obj;
1431	+
1432	+use crate::io::{merge, PlainRegisters};
1433	+use crate::irq::{Irq, IrqSource};
1434	+
1435	+pub const SCREEN_WIDTH: usize = 240;
1436	+pub const SCREEN_HEIGHT: usize = 160;
1437	+
1438	+pub const PALETTE_SIZE: usize = 0x400; // BG + OBJ palette RAM, 1 KiB
1439	+pub const VRAM_SIZE: usize = 0x18000; // 96 KiB
1440	+pub const OAM_SIZE: usize = 0x400; // OBJ attributes, 1 KiB
1441	+
1442	+/// 4 cycles per dot, 308 dots per line (gbatek: LCD Dimensions and Timings).
1443	+pub const CYCLES_PER_LINE: u32 = 1232;
1444	+/// Lines per frame, visible plus VBlank.
1445	+pub const LINES_PER_FRAME: u16 = 228;
1446	+/// First VBlank line.
1447	+pub const VBLANK_START_LINE: u16 = 160;
1448	+/// Cycle within a line at which the DISPSTAT H-Blank flag goes up. gbatek: "Although the drawing
1449	+/// time is only 960 cycles (240*4), the H-Blank flag is 0 for a total of 1006 cycles."
1450	+/// HBlank IRQ and HBlank DMA are raised at the same point. Tune here if timing tests disagree.
1451	+pub const HBLANK_START_CYCLE: u32 = 1006;
1452	+
1453	+const IO_START: u32 = 0x000;
1454	+const DISPSTAT: u32 = 0x004; // general LCD status: VBlank/HBlank/VCount flags, IRQ enables, LYC
1455	+const VCOUNT: u32 = 0x006; // current scanline (read only)
1456	+
1457	+const DISPSTAT_VBLANK_FLAG: u16 = 1 << 0;
1458	+const DISPSTAT_HBLANK_FLAG: u16 = 1 << 1;
1459	+const DISPSTAT_VCOUNT_FLAG: u16 = 1 << 2;
1460	+const DISPSTAT_VBLANK_IRQ_ENABLE: u16 = 1 << 3;
1461	+const DISPSTAT_HBLANK_IRQ_ENABLE: u16 = 1 << 4;
1462	+const DISPSTAT_VCOUNT_IRQ_ENABLE: u16 = 1 << 5;
1463	+/// Bits the CPU may write: the three IRQ enables and the LYC byte.
1464	+const DISPSTAT_WRITABLE: u16 = 0xFF38;
1465	+
1466	+/// Opaque black in the ABI framebuffer format 0xAABBGGRR.
1467	+const BLACK: u32 = 0xFF00_0000;
1468	+
1469	+/// One pixel of one layer for one scanline; only the compositor merges layers (Phase 3 contract).
1470	+#[derive(Clone, Copy, Default, Debug)]
1471	+pub struct LayerPixel {
1472	+    /// BGR555 colour.
1473	+    pub color: u16,
1474	+    /// 0 (front) to 3 (back).
1475	+    pub priority: u8,
1476	+    pub is_transparent: bool,
1477	+    pub is_semi_transparent_sprite: bool,
1478	+}
1479	+
1480	+/// What happened during a `Ppu::step`, for gba.rs to forward to DMA.
1481	+#[derive(Clone, Copy, Default, Debug)]
1482	+pub struct PpuEvents {
1483	+    /// HBlank started on a visible line (HBlank DMA trigger).
1484	+    pub hblank_started: bool,
1485	+    /// Line 160 started (VBlank DMA trigger).
1486	+    pub vblank_started: bool,
1487	+}
1488	+
1489	+pub struct Ppu {
1490	+    pub palette: Vec<u8>,
1491	+    pub vram: Vec<u8>,
1492	+    pub oam: Vec<u8>,
1493	+    /// 240x160 pixels in the ABI format 0xAABBGGRR.
1494	+    pub framebuffer: Vec<u32>,
1495	+    /// Current scanline, 0-227 (VCOUNT).
1496	+    pub vcount: u16,
1497	+    /// Cycle within the current line, 0-1231.
1498	+    pub line_cycle: u32,
1499	+    dispstat: u16,
1500	+    /// DISPCNT, BGxCNT, scroll, affine, window, blend registers: stored, read back as written.
1501	+    registers: PlainRegisters<0x30>,
1502	+}
1503	+
1504	+impl Ppu {
1505	+    pub fn new() -> Self {
1506	+        Ppu {
1507	+            palette: vec![0; PALETTE_SIZE],
1508	+            vram: vec![0; VRAM_SIZE],
1509	+            oam: vec![0; OAM_SIZE],
1510	+            framebuffer: vec![BLACK; SCREEN_WIDTH * SCREEN_HEIGHT],
1511	+            vcount: 0,
1512	+            line_cycle: 0,
1513	+            dispstat: 0,
1514	+            registers: PlainRegisters::new(IO_START),
1515	+        }
1516	+    }
1517	+
1518	+    /// Advance line timing by `cycles`, raising HBlank/VBlank/VCount IRQs on `irq`.
1519	+    pub fn step(&mut self, cycles: u32, irq: &mut Irq) -> PpuEvents {
1520	+        let mut events = PpuEvents::default();
1521	+        let mut remaining = cycles;
1522	+        while remaining > 0 {
1523	+            let next_boundary =
1524	+                if self.line_cycle < HBLANK_START_CYCLE { HBLANK_START_CYCLE } else { CYCLES_PER_LINE };
1525	+            let advance = remaining.min(next_boundary - self.line_cycle);
1526	+            self.line_cycle += advance;
1527	+            remaining -= advance;
1528	+            if self.line_cycle == HBLANK_START_CYCLE {
1529	+                self.enter_hblank(irq, &mut events);
1530	+            } else if self.line_cycle == CYCLES_PER_LINE {
1531	+                self.line_cycle = 0;
1532	+                self.start_next_line(irq, &mut events);
1533	+            }
1534	+        }
1535	+        events
1536	+    }
1537	+
1538	+    /// HBlank begins: draw the finished visible line, set the flag, raise IRQ.
1539	+    /// gbatek DISPSTAT: H-Blank conditions occur on every line, including VBlank lines.
1540	+    fn enter_hblank(&mut self, irq: &mut Irq, events: &mut PpuEvents) {
1541	+        if self.vcount < VBLANK_START_LINE {
1542	+            self.render_line(self.vcount as usize);
1543	+            events.hblank_started = true;
1544	+        }
1545	+        self.dispstat |= DISPSTAT_HBLANK_FLAG;
1546	+        if self.dispstat & DISPSTAT_HBLANK_IRQ_ENABLE != 0 {
1547	+            irq.request(IrqSource::HBlank);
1548	+        }
1549	+    }
1550	+
1551	+    /// Next scanline: update VCOUNT, the VBlank flag (lines 160-226) and the VCount match.
1552	+    fn start_next_line(&mut self, irq: &mut Irq, events: &mut PpuEvents) {
1553	+        self.dispstat &= !DISPSTAT_HBLANK_FLAG;
1554	+        self.vcount = (self.vcount + 1) % LINES_PER_FRAME;
1555	+
1556	+        if self.vcount == VBLANK_START_LINE {
1557	+            self.dispstat |= DISPSTAT_VBLANK_FLAG;
1558	+            events.vblank_started = true;
1559	+            if self.dispstat & DISPSTAT_VBLANK_IRQ_ENABLE != 0 {
1560	+                irq.request(IrqSource::VBlank);
1561	+            }
1562	+        } else if self.vcount == LINES_PER_FRAME - 1 {
1563	+            self.dispstat &= !DISPSTAT_VBLANK_FLAG;
1564	+        }
1565	+        self.update_vcount_match(irq);
1566	+    }
1567	+
1568	+    /// Compare VCOUNT with the LYC setting (DISPSTAT bits 8-15).
1569	+    fn update_vcount_match(&mut self, irq: &mut Irq) {
1570	+        let lyc = self.dispstat >> 8;
1571	+        if self.vcount == lyc {
1572	+            self.dispstat |= DISPSTAT_VCOUNT_FLAG;
1573	+            if self.dispstat & DISPSTAT_VCOUNT_IRQ_ENABLE != 0 {
1574	+                irq.request(IrqSource::VCounterMatch);
1575	+            }
1576	+        } else {
1577	+            self.dispstat &= !DISPSTAT_VCOUNT_FLAG;
1578	+        }
1579	+    }
1580	+
1581	+    /// Draw one visible scanline into the framebuffer. Stub: black.
1582	+    fn render_line(&mut self, line: usize) {
1583	+        let start = line * SCREEN_WIDTH;
1584	+        self.framebuffer[start..start + SCREEN_WIDTH].fill(BLACK);
1585	+    }
1586	+
1587	+    pub fn io_read16(&mut self, offset: u32) -> u16 {
1588	+        match offset {
1589	+            DISPSTAT => self.dispstat,
1590	+            VCOUNT => self.vcount,
1591	+            _ => self.registers.read(offset),
1592	+        }
1593	+    }
1594	+
1595	+    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
1596	+        match offset {
1597	+            DISPSTAT => self.dispstat = merge(self.dispstat, value, mask & DISPSTAT_WRITABLE),
1598	+            VCOUNT => {}
1599	+            _ => self.registers.write(offset, value, mask),
1600	+        }
1601	+    }
1602	+}
